def to_binary(n):
    if n == 0:
        return "0"
    bits = ""
    while n > 0:
        bits = str(n % 2) + bits   # the remainder is the next bit from the right
        n = n // 2
    return bits


def to_decimal(bits):
    total = 0
    for b in bits:
        total = total * 2 + int(b)
    return total


