def to_hex(n):
    digits = "0123456789ABCDEF"
    if n == 0:
        return "0"
    out = ""
    while n > 0:
        out = digits[n % 16] + out
        n //= 16
    return out

def codes(text):
    result = []
    for ch in text:
        result.append(ord(ch))
    return result

def rle(text):
    out = ""
    i = 0
    while i < len(text):
        j = i
        while j < len(text) and text[j] == text[i]:
            j += 1
        out += str(j - i) + text[i]
        i = j
    return out

def hex_to_rgb(code):
    h = code.lstrip("#")
    return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))

