def half_adder(a, b):
    return XOR(a, b), AND(a, b)          # (sum, carry)


def full_adder(a, b, carry_in):
    s1, c1 = half_adder(a, b)
    s2, c2 = half_adder(s1, carry_in)
    return s2, OR(c1, c2)


print("half adder: a b -> sum carry")
