    for b in (0, 1):
        print(f"  {a} {b} -> {half_adder(a, b)[0]}   {half_adder(a, b)[1]}")


def add_bits(x, y, width=8):
    result, carry = 0, 0
    for i in range(width):
        bit, carry = full_adder((x >> i) & 1, (y >> i) & 1, carry)
        result |= bit << i
    return result, carry


